const MAX_SAFE_FACTORIAL_INPUT = 170;

function validateInput(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) {
    throw new TypeError(`factorial expects a finite number, received ${String(n)}`);
  }
  if (!Number.isInteger(n)) {
    throw new RangeError(`factorial expects an integer, received ${n}`);
  }
  if (n < 0) {
    throw new RangeError(`factorial is undefined for negative input ${n}`);
  }
  return n;
}

function calculateFactorial(n) {
  const value = validateInput(n);
  let product = 1;
  for (let factor = 2; factor <= value; factor += 1) {
    product *= factor;
  }
  return product;
}

function calculateFactorialBig(n) {
  const value = validateInput(n);
  let product = 1n;
  for (let factor = 2n; factor <= BigInt(value); factor += 1n) {
    product *= factor;
  }
  return product;
}

function factorialTable(inputs) {
  const rows = [];
  for (const input of inputs) {
    const exact = calculateFactorialBig(input);
    const approximate = calculateFactorial(input);
    const isExactAsNumber = Number.isSafeInteger(approximate);
    rows.push({ input, exact, approximate, isExactAsNumber });
  }
  return rows;
}

function formatRow(row) {
  const { input, exact, approximate, isExactAsNumber } = row;
  const label = `${input}!`.padStart(5);
  const digits = exact.toString();
  const shown = digits.length > 24 ? `${digits.slice(0, 21)}...` : digits;
  const note = isExactAsNumber ? 'exact as Number' : `approx ${approximate.toExponential(6)}`;
  return `${label} = ${shown.padEnd(26)} (${note})`;
}

function main() {
  const samples = [0, 1, 5, 10, 20, 25, 100];
  const report = factorialTable(samples).map(formatRow);
  for (const line of report) {
    console.log(line);
  }

  const overflowPoint = samples.find((n) => !Number.isSafeInteger(calculateFactorial(n)));
  if (overflowPoint !== undefined) {
    console.log(`Number precision is lost starting at ${overflowPoint}!`);
  }

  const tooLarge = MAX_SAFE_FACTORIAL_INPUT + 1;
  const infinite = calculateFactorial(tooLarge);
  console.log(`${tooLarge}! as a Number is ${infinite}; use calculateFactorialBig instead.`);

  try {
    calculateFactorial(-3);
  } catch (error) {
    console.log(`Rejected: ${error.message}`);
  }
}

main();

module.exports = { calculateFactorial, calculateFactorialBig, factorialTable, formatRow };

