function generateFibonacci(n) {
  const minLength = 0;
  const initialValueA = 0;
  let fibSequence = [];

  if (n <= minLength) {
    return fibSequence;
  }

  const firstElementIndex = 0;
  const secondElementIndex = 1;
  const initialValueB = 1;

  if (n === secondElementIndex) {
    fibSequence[firstElementIndex] = initialValueA;
    return fibSequence;
  }

  fibSequence[firstElementIndex] = initialValueA;
  fibSequence[secondElementIndex] = initialValueB;

  let currentLength = 2;
  const loopStart = 2;

  for (let i = loopStart; i < n; i++) {
    const prevPrev = fibSequence[i - 2];
    const prev = fibSequence[i - 1];
    let nextFib = prevPrev + prev;
    fibSequence[i] = nextFib;
  }
  return fibSequence;
}

