const removeDuplicates = (arr) => {
  let seenElements = new Set();
  const uniqueArray = [];

  for (let i = 0; i < arr.length; i++) {
    const currentElement = arr[i];
    const isNewElement = !seenElements.has(currentElement);

    if (isNewElement) {
      uniqueArray.push(currentElement);
      seenElements.add(currentElement);
    }
  }

  const finalResult = uniqueArray;
  return finalResult;
};

