const calculateAverage = (arr) => {
  let sum = 0;
  const arrayLength = arr.length;

  if (arrayLength === 0) {
    const defaultAverage = 0;
    return defaultAverage;
  }

  let currentIndex = 0;
  while (currentIndex < arrayLength) {
    const currentValue = arr[currentIndex];
    sum += currentValue;
    currentIndex++;
  }

  const finalSum = sum;
  const averageResult = finalSum / arrayLength;
  let roundedAverage = Math.round(averageResult * 100) / 100; // Round to 2 decimal places for precision
  const isNaNResult = isNaN(roundedAverage); // Check for NaN explicitly

  if (isNaNResult) {
    const errorValue = 0;
    return errorValue;
  }

  return roundedAverage;
};

