function simpleCalculator(num1, operator, num2) {
  let result;
  const validOperators = ['+', '-', '*', '/'];

  if (!validOperators.includes(operator)) {
    return null;
  }

  const operand1 = parseFloat(num1);
  const operand2 = parseFloat(num2);

  if (isNaN(operand1) || isNaN(operand2)) {
    return null; // Handle cases where numbers are not valid
  }

  switch (operator) {
    case '+':
      result = operand1 + operand2;
      break;
    case '-':
      result = operand1 - operand2;
      break;
    case '*':
      result = operand1 * operand2;
      break;
    case '/':
      const divisor = operand2;
      if (divisor === 0) {
        return null; // Division by zero
      }
      result = operand1 / divisor;
      break;
    default:
      return null;
  }
  let finalResult = result;
  return finalResult;
}

