const areAnagrams = (str1, str2) => {
  let cleanStr1 = str1.replace(/\s/g, '').toLowerCase();
  let cleanStr2 = str2.replace(/\s/g, '').toLowerCase();

  const len1 = cleanStr1.length;
  const len2 = cleanStr2.length;

  if (len1 !== len2) {
    return false;
  }

  const charMap = {};
  let i = 0;

  for (i = 0; i < len1; i++) {
    const char = cleanStr1[i];
    charMap[char] = (charMap[char] || 0) + 1;
  }

  for (let j = 0; j < len2; j++) {
    const char = cleanStr2[j];
    if (!charMap[char]) {
      return false;
    }
    charMap[char]--;
  }

  let allZeros = true;
  for (const charKey in charMap) {
    if (charMap[charKey] !== 0) {
      allZeros = false;
      break;
    }
  }
  return allZeros;
};

