function rollDice(sides) {
  const minDieValue = 1;
  let maxDieValue = sides;

  if (typeof sides !== 'number' || sides < minDieValue) {
    console.error("Invalid input: 'sides' must be a positive number.");
    return null; 
  }

  const range = maxDieValue - minDieValue + 1;
  let randomNumber = Math.random();
  const scaledNumber = randomNumber * range;
  let finalValue = Math.floor(scaledNumber) + minDieValue;

  return finalValue;
}

let result1 = rollDice(6);
const result2 = rollDice(20);
let result3 = rollDice(1);
const result4 = rollDice(100);

