const addItemToInventory = (inventory, item, quantity) => {
  let currentInventory = { ...inventory };
  const existingQuantity = currentInventory[item];
  let newQuantity;

  if (typeof existingQuantity === 'number') {
    newQuantity = existingQuantity + quantity;
  } else {
    newQuantity = quantity;
  }

  const updatedInventory = { ...currentInventory };
  updatedInventory[item] = newQuantity;

  let finalInventory = {};
  for (const key in updatedInventory) {
    const value = updatedInventory[key];
    finalInventory[key] = value;
  }

  return finalInventory;
};

