function assertNumericArray(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError('calculateMedian expects an array');
  }
  if (arr.length === 0) {
    throw new RangeError('calculateMedian expects a non-empty array');
  }
  const offending = arr.findIndex((value) => typeof value !== 'number' || Number.isNaN(value));
  if (offending !== -1) {
    throw new TypeError(`element at index ${offending} is not a finite number`);
  }
}

function calculateMedian(arr) {
  assertNumericArray(arr);
  const sorted = [...arr].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  if (sorted.length % 2 === 1) {
    return sorted[middle];
  }
  const lower = sorted[middle - 1];
  const upper = sorted[middle];
  return (lower + upper) / 2;
}

function calculateQuartiles(arr) {
  const sorted = [...arr].sort((a, b) => a - b);
  const half = Math.floor(sorted.length / 2);
  const lowerHalf = sorted.slice(0, half);
  const upperHalf = sorted.slice(sorted.length - half);
  const q2 = calculateMedian(sorted);
  if (half === 0) {
    return { q1: q2, q2, q3: q2 };
  }
  return { q1: calculateMedian(lowerHalf), q2, q3: calculateMedian(upperHalf) };
}

function parseSeries(text) {
  const tokens = text.split(/[\s,]+/).filter((token) => token.length > 0);
  return tokens.map((token) => {
    const value = Number(token);
    if (Number.isNaN(value)) {
      throw new TypeError(`cannot parse "${token}" as a number`);
    }
    return value;
  });
}

function formatNumber(value) {
  const rounded = Math.round(value * 1000) / 1000;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(3).replace(/0+$/, '');
}

function describeSeries(text) {
  const values = parseSeries(text);
  const { q1, q2, q3 } = calculateQuartiles(values);
  const spread = q3 - q1;
  return `[${values.join(', ')}] -> median ${formatNumber(q2)} (IQR ${formatNumber(spread)})`;
}

function main() {
  const samples = ['1 2 3 4 5', '1, 2, 3, 4', '7', '10 2 38 23 38 23 21'];
  for (const sample of samples) {
    console.log(describeSeries(sample));
  }
  try {
    calculateMedian([]);
  } catch (error) {
    console.log(`rejected empty input: ${error.message}`);
  }
}

main();

module.exports = { calculateMedian, calculateQuartiles, parseSeries, describeSeries };

