const ELLIPSIS = '...';

function truncateString(str, maxLength) {
  if (typeof str !== 'string') {
    throw new TypeError(`truncateString expects a string, received ${typeof str}`);
  }
  const limit = Number(maxLength);
  if (!Number.isInteger(limit) || limit < 0) {
    throw new RangeError(`maxLength must be a non-negative integer, received ${maxLength}`);
  }
  if (str.length <= limit) {
    return str;
  }
  const keep = Math.max(0, limit - ELLIPSIS.length + 1);
  return str.slice(0, keep) + ELLIPSIS;
}

function truncateAll(items, maxLength) {
  if (!Array.isArray(items)) {
    throw new TypeError('truncateAll expects an array of strings');
  }
  return items.map((item) => truncateString(item, maxLength));
}

function describe(str, maxLength) {
  const result = truncateString(str, maxLength);
  const wasCut = result !== str;
  return {
    original: str,
    result,
    wasCut,
    removed: wasCut ? str.length - (result.length - ELLIPSIS.length) : 0,
  };
}

function formatReport(samples, maxLength) {
  const rows = samples.map((sample) => describe(sample, maxLength));
  const widest = rows.reduce((acc, row) => Math.max(acc, row.original.length), 0);
  const header = `truncating at maxLength=${maxLength}`;
  const lines = rows.map((row) => {
    const padded = row.original.padEnd(widest, ' ');
    const note = row.wasCut ? `cut (-${row.removed} chars)` : 'kept as-is';
    return `${padded} -> ${row.result.padEnd(maxLength + ELLIPSIS.length, ' ')} | ${note}`;
  });
  return [header, '-'.repeat(header.length), ...lines].join('\n');
}

function main() {
  const samples = [
    'Hello world, this is a long string',
    'Short',
    'Exactly ten',
    'A-Ok',
  ];
  const maxLength = 10;
  console.log(formatReport(samples, maxLength));

  const tiny = truncateString('Truncation', 1);
  console.log(`\nTight limit of 1 yields "${tiny}"`);

  const headlines = truncateAll(['Breaking news from the coast', 'Rain', 'Markets rally again'], 12);
  for (const headline of headlines) {
    console.log(`* ${headline}`);
  }
}

main();

module.exports = { truncateString, truncateAll, describe, formatReport };

