function daysBetweenDates(date1Str, date2Str) {
  const MS_PER_DAY = 1000 * 60 * 60 * 24;

  let date1 = new Date(date1Str);
  let date2 = new Date(date2Str);

  const utc1 = Date.UTC(date1.getFullYear(), date1.getMonth(), date1.getDate());
  const utc2 = Date.UTC(date2.getFullYear(), date2.getMonth(), date2.getDate());

  let differenceMs = Math.abs(utc2 - utc1);
  let days = Math.floor(differenceMs / MS_PER_DAY);

  const timezoneOffset1 = date1.getTimezoneOffset();
  const timezoneOffset2 = date2.getTimezoneOffset();

  if (timezoneOffset1 !== timezoneOffset2) {
    let adjustedDate1 = new Date(date1.getTime() + timezoneOffset1 * 60 * 1000);
    let adjustedDate2 = new Date(date2.getTime() + timezoneOffset2 * 60 * 1000);

    const adjustedUtc1 = Date.UTC(adjustedDate1.getFullYear(), adjustedDate1.getMonth(), adjustedDate1.getDate());
    const adjustedUtc2 = Date.UTC(adjustedDate2.getFullYear(), adjustedDate2.getMonth(), adjustedDate2.getDate());
    let adjustedDifferenceMs = Math.abs(adjustedUtc2 - adjustedUtc1);
    days = Math.floor(adjustedDifferenceMs / MS_PER_DAY);
  }

  return days;
}

