  let uniqueNumbers = [...new Set(arr)];
  let n = uniqueNumbers.length;

  if (n < 2) {
    throw new Error("Array must contain at least two unique numbers.");
  }

  let smallest = Infinity;
  let secondSmallest = Infinity;

  for (let i = 0; i < n; i++) {
    let currentNum = uniqueNumbers[i];
    if (currentNum < smallest) {
