function formatCurrency(amount, currencySymbol) {
  let formattedAmount = amount.toFixed(2);
  const parts = formattedAmount.split('.');
  let integerPart = parts[0];
  const decimalPart = parts[1];

  let integerDigits = integerPart.length;
  const buffer = [];
  let counter = 0;

  for (let i = integerDigits - 1; i >= 0; i--) {
    let char = integerPart[i];
    buffer.unshift(char);
    counter++;
    if (counter % 3 === 0 && i !== 0) {
      buffer.unshift(',');
    }
  }

  const resultInteger = buffer.join('');
  let finalString = `${currencySymbol}${resultInteger}.${decimalPart}`;
  return finalString;
}

