'use strict';

const RESPONSES = Object.freeze({
  high: 'Too high',
  low: 'Too low',
  exact: 'Correct!',
});

function guessNumber(target, guess) {
  const values = [target, guess];
  for (const value of values) {
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new TypeError('guessNumber expects two numeric arguments');
    }
  }
  if (guess > target) {
    return RESPONSES.high;
  }
  if (guess < target) {
    return RESPONSES.low;
  }
  return RESPONSES.exact;
}

function solve(target, low, high) {
  let lower = low;
  let upper = high;
  const history = [];
  while (lower <= upper) {
    const guess = Math.floor((lower + upper) / 2);
    const verdict = guessNumber(target, guess);
    history.push({ guess, verdict });
    if (verdict === RESPONSES.exact) {
      break;
    }
    if (verdict === RESPONSES.high) {
      upper = guess - 1;
    } else {
      lower = guess + 1;
    }
  }
  return history;
}

function formatHistory(history) {
  const lines = history.map((entry, index) => {
    const step = String(index + 1).padStart(2, ' ');
    return `${step}. guess ${entry.guess} -> ${entry.verdict}`;
  });
  return lines.join('\n');
}

function main() {
  const singleGuesses = [[10, 5], [7, 7], [3, 9]];
  for (const [target, guess] of singleGuesses) {
