'use strict';

var RESPONSES = Object.freeze({
  high: 'Too high',
  low: 'Too low',
  exact: 'Correct!',
});

function guessNumber(target, guess) {
  var values = [target, guess];
  for (var value of values) {
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new TypeError('guessNumber expects two numeric arguments');
    }
  }
  if (guess > target) {
    return RESPONSES.high;
  }
  if (guess < target) {
    return RESPONSES.low;
  }
  return RESPONSES.exact;
}

function solve(target, low, high) {
  var lower = low;
  var upper = high;
  var history = [];
  while (lower <= upper) {
    var guess = Math.floor((lower + upper) / 2);
    var verdict = guessNumber(target, guess);
    history.push({ guess, verdict });
    if (verdict === RESPONSES.exact) {
      break;
    }
    if (verdict === RESPONSES.high) {
      upper = guess - 1;
    } else {
      lower = guess + 1;
    }
  }
  return history;
}

function formatHistory(history) {
  var lines = history.map((entry, index) => {
    var step = String(index + 1).padStart(2, ' ');
    return `${step}. guess ${entry.guess} -> ${entry.verdict}`;
  });
  return lines.join('\n');
}

function main() {
  var singleGuesses = [[10, 5], [7, 7], [3, 9]];
  for (var [target, guess] of singleGuesses) {
    console.log(`guessNumber(${target}, ${guess}) = ${guessNumber(target, guess)}`);
  }

  var secret = 42;
  var trail = solve(secret, 1, 100);
  console.log(`\nSearching for ${secret} between 1 and 100:`);
  console.log(formatHistory(trail));

  var found = trail[trail.length - 1];
  console.log(`Solved in ${trail.length} guesses (final guess ${found.guess}).`);
}

main();

module.exports = { guessNumber, solve, formatHistory };

