function startsWith(str, prefix) {
  if (typeof str !== 'string' || typeof prefix !== 'string') {
    throw new TypeError('startsWith expects two strings');
  }
  const limit = prefix.length;
  if (limit > str.length) {
    return false;
  }
  for (let i = 0; i < limit; i += 1) {
    if (str[i] !== prefix[i]) {
      return false;
    }
  }
  return true;
}

function startsWithIgnoreCase(str, prefix) {
  return startsWith(str.toLowerCase(), prefix.toLowerCase());
}

function stripPrefix(str, prefix) {
  return startsWith(str, prefix) ? str.slice(prefix.length) : str;
}

function filterByPrefix(words, prefix) {
  const matches = [];
  for (const word of words) {
    if (startsWithIgnoreCase(word, prefix)) {
      matches.push(word);
    }
  }
  return matches;
}

function longestCommonPrefix(words) {
  if (words.length === 0) {
    return '';
  }
  let candidate = words[0];
  for (const word of words.slice(1)) {
    while (candidate.length > 0 && !startsWith(word, candidate)) {
      candidate = candidate.slice(0, -1);
    }
  }
  return candidate;
}

function formatCheck(str, prefix) {
  const verdict = startsWith(str, prefix);
  return `startsWith('${str}', '${prefix}') -> ${verdict}`;
}

function main() {
  const checks = [
    ['Hello World', 'Hello'],
    ['JavaScript', 'JavaScripX'],
    ['', ''],
    ['short', 'a much longer prefix'],
  ];
  for (const [str, prefix] of checks) {
    console.log(formatCheck(str, prefix));
  }

  const languages = ['JavaScript', 'Java', 'Python', 'javaFX', 'Ruby'];
  const javaFamily = filterByPrefix(languages, 'java');
  console.log(`Names starting with "java": ${javaFamily.join(', ')}`);
  console.log(`Longest common prefix: "${longestCommonPrefix(javaFamily)}"`);

  const filename = 'src/index.test.js';
  const trimmed = stripPrefix(filename, 'src/');
  console.log(`Without the "src/" prefix: ${trimmed}`);
}

main();

