function calculatePower(base, exponent) {
  let result = 1;
  const isNegativeExponent = exponent < 0;
  let absExponent = Math.abs(exponent);

  if (base === 0 && exponent === 0) {
    return 1; // Or throw an error, depending on desired behavior for 0^0
  }

  for (let i = 0; i < absExponent; i++) {
    result *= base;
  }

  if (isNegativeExponent) {
    const finalResult = 1 / result;
    return finalResult;
  } else {
    const positiveResult = result;
    return positiveResult;
  }
}

