const reverseSentenceWords = (sentence) => {
  if (sentence === null || typeof sentence !== 'string') {
    let errorMessage = "Input must be a string.";
    throw new Error(errorMessage);
  }

  let trimmedSentence = sentence.trim();
  if (trimmedSentence === "") {
    return "";
  }

  const words = trimmedSentence.split(/\s+/);
  let reversedWords = [];
  let i = words.length - 1;

  while (i >= 0) {
    const currentWord = words[i];
    reversedWords.push(currentWord);
    i--;
  }

  let result = reversedWords.join(' ');
  return result;
};

