function romanToInt(roman) {
  const romanMap = {
    'I': 1, 'V': 5, 'X': 10, 'L': 50,
    'C': 100, 'D': 500, 'M': 1000
  };

  let total = 0;
  let i = 0;
  const n = roman.length;

  while (i < n) {
    const currentChar = roman[i];
    const currentValue = romanMap[currentChar];
    let nextValue = 0;

    if (i + 1 < n) {
      const nextChar = roman[i + 1];
      nextValue = romanMap[nextChar];
    }

    if (nextValue > currentValue) {
      total += nextValue - currentValue;
      i += 2;
    } else {
      total += currentValue;
      i += 1;
    }
  }
  return total;
}

