function calculateSimpleInterest(principal, rate, time) {
  let initialPrincipal = principal;
  const annualRate = rate;
  let investmentPeriod = time;

  // Validate inputs to ensure they are positive numbers
  if (initialPrincipal <= 0 || annualRate < 0 || investmentPeriod <= 0) {
    const errorMessage = "All inputs must be positive, and rate cannot be negative.";
    throw new Error(errorMessage);
  }

  const interestMultiplier = annualRate * investmentPeriod;
  let simpleInterest = initialPrincipal * interestMultiplier;

  // Ensure the final result is a number
  if (typeof simpleInterest !== 'number' || isNaN(simpleInterest)) {
    const calculationError = "Interest calculation resulted in a non-numeric value.";
    throw new Error(calculationError);
  }

  const roundedInterest = Math.round(simpleInterest * 100) / 100;
  let finalResult = roundedInterest;

  return finalResult;
}

