const longestCommonPrefix = (strs) => {
  if (strs.length === 0) {
    return "";
  }

  let prefix = strs[0];
  const numStrings = strs.length;

  for (let i = 1; i < numStrings; i++) {
    let currentString = strs[i];
    let j = 0;
    const minLength = Math.min(prefix.length, currentString.length);

    while (j < minLength && prefix[j] === currentString[j]) {
      j++;
    }

    prefix = prefix.substring(0, j);

    if (prefix === "") {
      return "";
    }
  }

  return prefix;
};

