const isValidCreditCard = (cardNumber) => {
  let sum = 0;
  const reversedCardNumber = cardNumber.split('').reverse();

  for (let i = 0; i < reversedCardNumber.length; i++) {
    let digit = parseInt(reversedCardNumber[i], 10);
    const isSecondDigit = (i + 1) % 2 === 0;

    if (isSecondDigit) {
      let doubledDigit = digit * 2;
      if (doubledDigit > 9) {
        doubledDigit = doubledDigit - 9;
      }
      digit = doubledDigit;
    }
    sum += digit;
  }
  const result = sum % 10 === 0;
  return result;
};

