let generateAcronym = (phrase) => {
  const words = phrase.split(/[\s-]+/);
  let acronym = '';
  const regex = /[a-zA-Z]/;

  for (let i = 0; i < words.length; i++) {
    let word = words[i];
    if (word.length > 0) {
      let firstChar = '';
      let charIndex = 0;
      while (charIndex < word.length) {
        const char = word[charIndex];
        if (regex.test(char)) {
          firstChar = char.toUpperCase();
          break;
        }
        charIndex++;
      }
      acronym += firstChar;
    }
  }
  return acronym;
};

