function largeFactorial(n) {
  if (n === 0) {
    return '1';
  }

  let result = [1];
  let i = 1;

  while (i <= n) {
    let carry = 0;
    let j = 0;
    const currentResultLength = result.length;

    while (j < currentResultLength || carry !== 0) {
      let digit = j < currentResultLength ? result[j] : 0;
      let product = digit * i + carry;
      let newDigit = product % 10;
      carry = Math.floor(product / 10);

      if (j < currentResultLength) {
        result[j] = newDigit;
      } else {
        result.push(newDigit);
      }
      j++;
    }
    i++;
  }

  const finalResultString = result.reverse().join('');
  return finalResultString;
}

