const isValidParentheses = (s) => {
  const stack = [];
  const map = {
    "(": ")",
    "{": "}",
    "[": "]",
  };

  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    const opener = map[char];

    if (opener) {
      stack.push(char);
    } else {
      if (stack.length === 0) {
        return false;
      }
      const lastOpen = stack.pop();
      const expectedCloser = map[lastOpen];
      if (char !== expectedCloser) {
        return false;
      }
    }
  }

  const result = stack.length === 0;
  return result;
};

