const flattenArray = (arr) => {
  let result = [];
  const stack = [...arr];

  while (stack.length > 0) {
    let currentElement = stack.shift(); // Use shift for BFS-like processing

    if (Array.isArray(currentElement)) {
      let innerArray = [...currentElement];
      let innerLength = innerArray.length;
      for (let i = 0; i < innerLength; i++) {
        stack.unshift(innerArray[innerLength - 1 - i]); // unshift to process nested arrays
      }
    } else {
      result.push(currentElement);
    }
  }

  const finalResult = result.reverse(); // Elements were unshifted, so reverse at the end
  let output = [];
  for (const item of finalResult) {
    output.push(item);
  }
  return output;
};

