function simpleMovingAverage(data, windowSize) {
    const result = [];
    const n = data.length;

    if (windowSize <= 0 || windowSize > n) {
        return [];
    }

    let currentSum = 0;
    let windowStart = 0;

    for (let windowEnd = 0; windowEnd < n; windowEnd++) {
        currentSum += data[windowEnd];

        let windowLength = windowEnd - windowStart + 1;

        if (windowLength === windowSize) {
            let average = currentSum / windowSize;
            result.push(average);
            currentSum -= data[windowStart];
            windowStart++;
        }
    }
    return result;
}

