function validateInput(nums) {
  if (!Array.isArray(nums)) {
    throw new TypeError('majorityElement expects an array of numbers');
  }
  if (nums.length === 0) {
    throw new RangeError('majorityElement expects a non-empty array');
  }
  const badIndex = nums.findIndex((value) => typeof value !== 'number' || Number.isNaN(value));
  if (badIndex !== -1) {
    throw new TypeError(`element at index ${badIndex} is not a valid number`);
  }
  return nums;
}

function findCandidate(nums) {
  let candidate = nums[0];
  let balance = 0;
  for (const value of nums) {
    if (balance === 0) {
      candidate = value;
      balance = 1;
    } else if (value === candidate) {
      balance += 1;
    } else {
      balance -= 1;
    }
  }
  return candidate;
}

function countOccurrences(nums, target) {
  let total = 0;
  for (const value of nums) {
    if (value === target) {
      total += 1;
    }
  }
  return total;
}

function majorityElement(nums) {
  validateInput(nums);
  const candidate = findCandidate(nums);
  const threshold = Math.floor(nums.length / 2);
  const occurrences = countOccurrences(nums, candidate);
  if (occurrences <= threshold) {
    throw new Error('no majority element exists in the given array');
  }
  return candidate;
}

function describeMajority(nums) {
  const winner = majorityElement(nums);
  const occurrences = countOccurrences(nums, winner);
  const share = ((occurrences / nums.length) * 100).toFixed(1);
  return `[${nums.join(', ')}] -> ${winner} (${occurrences}/${nums.length}, ${share}%)`;
}

function main() {
  const samples = [
    [3, 2, 3],
    [2, 2, 1, 1, 1, 2, 2],
    [7],
    [-4, -4, 9, -4, 0],
  ];
  for (const sample of samples) {
    console.log(describeMajority(sample));
  }
  const broken = [1, 2, 3, 4];
  try {
    majorityElement(broken);
  } catch (error) {
    console.log(`[${broken.join(', ')}] -> ${error.message}`);
  }
}

main();

module.exports = { majorityElement, describeMajority };

