const stringPermutations = (str) => {
  let result = [];
  const chars = str.split('');

  const backtrack = (currentPermutation, remainingChars) => {
    let currentLength = currentPermutation.length;
    let totalLength = str.length;

    if (currentLength === totalLength) {
      result.push(currentPermutation.join(''));
      return;
    }

    const used = new Set();
    let i = 0;
    while (i < remainingChars.length) {
      let char = remainingChars[i];
      if (!used.has(char)) {
        used.add(char);
        const nextRemainingChars = [...remainingChars.slice(0, i), ...remainingChars.slice(i + 1)];
        backtrack([...currentPermutation, char], nextRemainingChars);
      }
      i++;
    }
  };

  backtrack([], chars);
  let uniqueResult = Array.from(new Set(result));
  return uniqueResult;
};

