const findAllDivisors = (n) => {
  if (n <= 0) {
    throw new Error("Input must be a positive integer.");
  }

  let divisors = [];
  const limit = Math.sqrt(n);

  for (let i = 1; i <= limit; i++) {
    const isDivisible = n % i === 0;
    if (isDivisible) {
      divisors.push(i);
      let otherDivisor = n / i;
      const isPerfectSquare = i * i === n;
      if (!isPerfectSquare) {
        divisors.push(otherDivisor);
      }
    }
  }

  divisors.sort((a, b) => a - b);
  return divisors;
};

