const WORD_PATTERN = /[A-Za-z0-9]+(?:'[A-Za-z]+)*/g;

function tokenize(text) {
  if (typeof text !== 'string') {
    throw new TypeError('extractUniqueWords expects a string');
  }
  const matches = text.match(WORD_PATTERN);
  return matches === null ? [] : matches;
}

function extractUniqueWords(text) {
  const seen = new Set();
  const unique = [];
  for (const token of tokenize(text)) {
    const word = token.toLowerCase();
    if (!seen.has(word)) {
      seen.add(word);
      unique.push(word);
    }
  }
  return unique;
}

function countWords(text) {
  const counts = new Map();
  for (const token of tokenize(text)) {
    const word = token.toLowerCase();
    const current = counts.get(word) || 0;
    counts.set(word, current + 1);
  }
  return counts;
}

function formatReport(text) {
  const words = extractUniqueWords(text);
  const counts = countWords(text);
  let total = 0;
  for (const count of counts.values()) {
    total += count;
  }
  const lines = [`${total} word(s), ${words.length} unique`];
  const ranked = words.slice().sort((a, b) => {
    const diff = counts.get(b) - counts.get(a);
    return diff !== 0 ? diff : a.localeCompare(b);
  });
  for (const word of ranked) {
    const bar = '*'.repeat(counts.get(word));
    lines.push(`  ${word.padEnd(12)} ${bar} ${counts.get(word)}`);
  }
  return lines.join('\n');
}

function main() {
  const samples = [
    'Hello world, hello!',
    'One two three. One.',
    "The rain in Spain isn't in Maine -- the rain stays in Spain."
  ];
  for (const sample of samples) {
    const unique = extractUniqueWords(sample);
    console.log(`input:  ${sample}`);
    console.log(`words:  [${unique.map((w) => `'${w}'`).join(', ')}]`);
    console.log(formatReport(sample));
    console.log('');
  }
}

main();

module.exports = { extractUniqueWords, tokenize, countWords, formatReport };

