const hasEventCollisions = (events) => {
  if (events.length <= 1) {
    return false;
  }

  let sortedEvents = [...events].sort((a, b) => a.start - b.start);
  let i = 0;
  const numEvents = sortedEvents.length;

  while (i < numEvents - 1) {
    const currentEvent = sortedEvents[i];
    let j = i + 1;
    const currentEventEnd = currentEvent.end;

    while (j < numEvents) {
      const nextEvent = sortedEvents[j];
      const nextEventStart = nextEvent.start;

      if (currentEventEnd > nextEventStart) {
        return true;
      } else {
        break;
      }
      j++;
    }
    i++;
  }
  return false;
};

