function replaceAllOccurrences(text, find, replace) {
  let result = '';
  let lastIndex = 0;
  const findLength = find.length;

  for (let i = 0; i < text.length; i++) {
    const currentSlice = text.substring(i, i + findLength);
    if (currentSlice === find) {
      result += text.substring(lastIndex, i);
      result += replace;
      i += findLength - 1;
      lastIndex = i + 1;
    }
  }

  const remainingText = text.substring(lastIndex);
  result += remainingText;

  return result;
}

