function validateRange(start, end, step) {
  const args = [start, end, step];
  const badIndex = args.findIndex((value) => typeof value !== 'number' || !Number.isFinite(value));
  if (badIndex !== -1) {
    const names = ['start', 'end', 'step'];
    throw new TypeError(`${names[badIndex]} must be a finite number`);
  }
  if (step === 0) {
    throw new RangeError('step must not be zero');
  }
  const descending = end < start;
  if (descending && step > 0) {
    throw new RangeError('step must be negative when end is below start');
  }
  if (!descending && step < 0) {
    throw new RangeError('step must be positive when end is above start');
  }
}

function range(start, end, step = 1) {
  validateRange(start, end, step);
  const span = end - start;
  const count = Math.floor(span / step) + 1;
  const values = new Array(count);
  for (let i = 0; i < count; i += 1) {
    values[i] = start + i * step;
  }
  return values;
}

function sum(values) {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return total;
}

function describe(start, end, step = 1) {
  const values = range(start, end, step);
  const call = step === 1 ? `range(${start}, ${end})` : `range(${start}, ${end}, ${step})`;
  const listed = values.join(', ');
  return `${call} -> [${listed}] (count ${values.length}, sum ${sum(values)})`;
}

function main() {
  const cases = [
    [1, 5],
    [1, 10, 2],
    [0, 1, 0.25],
    [10, 1, -3],
    [7, 7],
  ];
  for (const [start, end, step] of cases) {
    const line = step === undefined ? describe(start, end) : describe(start, end, step);
    console.log(line);
  }
  const invalid = [[1, 5, 0], [5, 1, 1], [1, '5', 1]];
  for (const [start, end, step] of invalid) {
    try {
      range(start, end, step);
    } catch (error) {
      console.log(`rejected range(${start}, ${end}, ${step}): ${error.message}`);
    }
  }
}

main();

module.exports = { range, describe };

