const longestPalindromeSubstring = (s) => {
  let maxLength = 0;
  let start = 0;
  const n = s.length;

  if (n < 2) {
    return s;
  }

  for (let i = 0; i < n; i++) {
    let left = i;
    let right = i;

    while (left >= 0 && right < n && s[left] === s[right]) {
      let currentLength = right - left + 1;
      if (currentLength > maxLength) {
        maxLength = currentLength;
        start = left;
      }
      left--;
      right++;
    }

    left = i;
    right = i + 1;
    while (left >= 0 && right < n && s[left] === s[right]) {
      let currentLength = right - left + 1;
      if (currentLength > maxLength) {
        maxLength = currentLength;
        start = left;
      }
      left--;
      right++;
    }
  }

  const result = s.substring(start, start + maxLength);
  return result;
};

