function findSingleNumber(nums) {
  let uniqueElements = new Set();
  const n = nums.length;
  let singleNumber = 0;

  for (let i = 0; i < n; i++) {
    const currentNum = nums[i];
    if (uniqueElements.has(currentNum)) {
      uniqueElements.delete(currentNum);
    } else {
      uniqueElements.add(currentNum);
    }
  }

  const iterator = uniqueElements.values();
  const firstValue = iterator.next().value;
  singleNumber = firstValue;
  const result = singleNumber;
  return result;
}

