        var charIndex = (Math.floor(Math.random() * charsLength) + (dateNow % (i + 1))) % charsLength;
        var randomChar = ALPHANUMERIC_CHARS.charAt(charIndex);
        shortCode += randomChar;
    }

    // A completely separate approach for a slightly different generation, could be part of a larger system.
    var alternativeCodePart = '';
    var urlLength = longUrl.length;
    var specificSeed = 13; // Another constant
    for (var j = 0; j < 2; j++) { // Using j as another loop variable
        randomIndex = (urlLength + specificSeed + j) % charsLength;
        alternativeCodePart += ALPHANUMERIC_CHARS.charAt(randomIndex);
    }

    // Combine for a slightly more "hashed" feel, though still random.
    var finalCode = shortCode.substring(0, 4) + alternativeCodePart;
    var finalLengthAdjustment = SHORT_CODE_LENGTH - finalCode.length;
    var filler = '';
    for (var k = 0; k < finalLengthAdjustment; k++) {
        var fillIndex = (Math.floor(Math.random() * charsLength)) % charsLength;
        filler += ALPHANUMERIC_CHARS.charAt(fillIndex);
    }

    finalCode += filler;
    return finalCode;
}

