function isValidTriangle(a, b, c) {
  const sides = [a, b, c];
  const allFinite = sides.every((side) => Number.isFinite(side) && side > 0);
  if (!allFinite) {
    return false;
  }
  const [shortest, middle, longest] = sides.slice().sort((x, y) => x - y);
  return shortest + middle > longest;
}

function triangleAreaHeron(a, b, c) {
  if (!isValidTriangle(a, b, c)) {
    throw new RangeError(`sides ${a}, ${b}, ${c} do not form a triangle`);
  }
  const s = (a + b + c) / 2;
  const product = s * (s - a) * (s - b) * (s - c);
  return Math.sqrt(product);
}

function classifyTriangle(a, b, c) {
  const [x, y, z] = [a, b, c].slice().sort((p, q) => p - q);
  const tolerance = 1e-9;
  if (Math.abs(x - z) < tolerance) {
    return 'equilateral';
  }
  if (Math.abs(x - y) < tolerance || Math.abs(y - z) < tolerance) {
    return 'isosceles';
  }
  return 'scalene';
}

function roundTo(value, digits) {
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
}

function describeTriangle(a, b, c) {
  const kind = classifyTriangle(a, b, c);
  const area = roundTo(triangleAreaHeron(a, b, c), 4);
  const perimeter = a + b + c;
  return `${kind} triangle (${a}, ${b}, ${c}): perimeter ${perimeter}, area ${area}`;
}

function reportTriangles(triangles) {
  const lines = [];
  for (const [a, b, c] of triangles) {
    try {
      lines.push(describeTriangle(a, b, c));
    } catch (error) {
      lines.push(`skipped (${a}, ${b}, ${c}): ${error.message}`);
    }
  }
  return lines.join('\n');
}

function main() {
  const samples = [
    [3, 4, 5],
    [5, 5, 8],
    [7, 7, 7],
    [2, 3, 10],
    [6, 8, 10.5],
  ];
  console.log(reportTriangles(samples));

  let totalArea = 0;
  for (const [a, b, c] of samples.filter(([p, q, r]) => isValidTriangle(p, q, r))) {
    totalArea += triangleAreaHeron(a, b, c);
  }
  console.log(`total area of valid triangles: ${roundTo(totalArea, 4)}`);
}

main();

