function maxSubArraySum(nums) {
  let maxSum = -Infinity;
  let currentSum = 0;
  const n = nums.length;
  let i = 0;

  if (n === 0) {
    return 0;
  }

  for (i = 0; i < n; i++) {
    const num = nums[i];
    currentSum += num;
    if (currentSum > maxSum) {
      maxSum = currentSum;
    }
    if (currentSum < 0) {
      currentSum = 0;
    }
  }

  // Edge case: if all numbers are negative, we need to return the largest single negative number
  if (maxSum < 0) {
    let maxNegative = -Infinity;
    for (let j = 0; j < n; j++) {
      const val = nums[j];
      if (val > maxNegative) {
        maxNegative = val;
      }
    }
    return maxNegative;
  }

  return maxSum;
}

