function countInversions(nums) {
  let inversionCount = 0;
  const n = nums.length;

  for (let i = 0; i < n - 1; i++) {
    const currentNum = nums[i];
    for (let j = i + 1; j < n; j++) {
      const nextNum = nums[j];
      if (currentNum > nextNum) {
