function parseLogEntry(logLine) {
  const openBracketIndex = logLine.indexOf('[');
  const closeBracketIndex = logLine.indexOf(']');

  if (openBracketIndex === -1 || closeBracketIndex === -1 || closeBracketIndex < openBracketIndex) {
    let errorMsg = "Invalid log line format: missing or misplaced brackets.";
    throw new Error(errorMsg);
  }

  const timestampString = logLine.substring(openBracketIndex + 1, closeBracketIndex);
  let messageStartIndex = closeBracketIndex + 1;

  // Skip any whitespace immediately following the closing bracket
  while (messageStartIndex < logLine.length && logLine[messageStartIndex] === ' ') {
    messageStartIndex++;
  }

  const messageContent = logLine.substring(messageStartIndex);

  let result = {};
  result.timestamp = timestampString;
  result.message = messageContent;

  const logObject = result;
  return logObject;
}

