const MS_PER_DAY = 24 * 60 * 60 * 1000;
const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

function parseDateString(dateString) {
  if (typeof dateString !== 'string') {
    throw new TypeError('Expected a date string in YYYY-MM-DD format');
  }
  const match = DATE_PATTERN.exec(dateString.trim());
  if (!match) {
    throw new RangeError(`Malformed date: "${dateString}" (expected YYYY-MM-DD)`);
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const utcMidnight = Date.UTC(year, month - 1, day);
  const roundTrip = new Date(utcMidnight);
  if (roundTrip.getUTCMonth() !== month - 1 || roundTrip.getUTCDate() !== day) {
    throw new RangeError(`Impossible calendar date: "${dateString}"`);
  }
  return utcMidnight;
}

function todayAsUtcMidnight(now = new Date()) {
  return Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());
}

function daysUntil(futureDateString) {
  const target = parseDateString(futureDateString);
  const today = todayAsUtcMidnight();
  const difference = Math.round((target - today) / MS_PER_DAY);
  return difference > 0 ? difference : 0;
}

function describeCountdown(futureDateString) {
  const remaining = daysUntil(futureDateString);
  if (remaining === 0) {
    const target = parseDateString(futureDateString);
    const label = target < todayAsUtcMidnight() ? 'already passed' : 'is today';
    return `${futureDateString} ${label}`;
  }
  const unit = remaining === 1 ? 'day' : 'days';
  return `${futureDateString} is ${remaining} full ${unit} away`;
}

function buildCountdownReport(dateStrings) {
  const lines = [];
  for (const entry of dateStrings) {
    try {
      lines.push(describeCountdown(entry));
    } catch (error) {
      lines.push(`${entry}: ${error.message}`);
    }
  }
  return lines.join('\n');
}

function main(argv) {
  let inputs = argv.slice(2);
  if (inputs.length === 0) {
    const now = new Date();
    const nextYear = new Date(Date.UTC(now.getUTCFullYear() + 1, 0, 1));
    inputs = [nextYear.toISOString().slice(0, 10)];
  }
  console.log(buildCountdownReport(inputs));
}

if (require.main === module) {
  main(process.argv);
}

module.exports = { daysUntil, describeCountdown, buildCountdownReport, parseDateString };

