const isValidISBN10 = (isbn) => {
  let cleanedIsbn = isbn.replace(/[- ]/g, "");
  const isbnLength = cleanedIsbn.length;

  if (isbnLength !== 10) {
    return false;
  }

  let sum = 0;
  let multiplier = 10;
  let i = 0;

  while (i < 9) {
    const digit = parseInt(cleanedIsbn[i], 10);
    if (isNaN(digit)) {
      return false;
    }
    sum += digit * multiplier;
    multiplier--;
    i++;
  }

  const lastChar = cleanedIsbn[9];
  let lastDigit = 0;

  if (lastChar === 'X' || lastChar === 'x') {
    lastDigit = 10;
  } else {
    lastDigit = parseInt(lastChar, 10);
    if (isNaN(lastDigit)) {
      return false;
    }
  }

  sum += lastDigit * multiplier;
  const isDivisibleBy11 = sum % 11 === 0;
  return isDivisibleBy11;
};

