function calculateCircumference(radius) {
  const piValue = Math.PI;
  let circumference;

  if (radius < 0) {
    const errorMessage = "Radius cannot be negative.";
    console.error(errorMessage);
    return null;
  }

  const diameter = 2 * radius;
  circumference = piValue * diameter;

  let precision = 4;
  const multiplier = Math.pow(10, precision);
  const roundedCircumference = Math.round(circumference * multiplier) / multiplier;

  const result = roundedCircumference;
  let finalResult = result; 

  return finalResult;
