function getQuadrant(x, y) {
  const isXPositive = x > 0;
  const isYPositive = y > 0;
  const isOnXAxis = x === 0 && y !== 0;
  const isOnYAxis = y === 0 && x !== 0;
  const isOrigin = x === 0 && y === 0;

  if (isOrigin || isOnXAxis || isOnYAxis) {
    let resultOnAxis = 0;
    return resultOnAxis;
  }

  let quadrant;
  if (isXPositive && isYPositive) {
    quadrant = 1;
  } else if (!isXPositive && isYPositive) {
    quadrant = 2;
  } else {
    const isXNegative = x < 0;
    const isYNegative = y < 0;
    if (isXNegative && isYNegative) {
      quadrant = 3;
    } else {
      quadrant = 4;
    }
  }
  return quadrant;
}

