function validateTossCount(numTosses) {
  const isInteger = Number.isInteger(numTosses);
  if (!isInteger || numTosses < 0) {
    throw new RangeError(`numTosses must be a non-negative integer, got ${numTosses}`);
  }
  return numTosses;
}

function tossCoin() {
  const draw = Math.random();
  return draw < 0.5 ? 'heads' : 'tails';
}

function simulateCoinTosses(numTosses) {
  const total = validateTossCount(numTosses);
  const counts = { heads: 0, tails: 0 };
  for (let i = 0; i < total; i += 1) {
    const outcome = tossCoin();
    counts[outcome] += 1;
  }
  return counts;
}

function summarize(counts) {
  const total = counts.heads + counts.tails;
  if (total === 0) {
    return { total, headsShare: 0, tailsShare: 0, deviation: 0 };
  }
  const headsShare = counts.heads / total;
  const tailsShare = counts.tails / total;
  return {
    total,
    headsShare,
    tailsShare,
    deviation: Math.abs(headsShare - 0.5)
  };
}

function formatPercent(fraction) {
  const percent = fraction * 100;
  return `${percent.toFixed(1)}%`;
}

function formatReport(counts) {
  const stats = summarize(counts);
  const parts = [
    `${stats.total} tosses`,
    `heads: ${counts.heads} (${formatPercent(stats.headsShare)})`,
    `tails: ${counts.tails} (${formatPercent(stats.tailsShare)})`,
    `deviation from fair: ${formatPercent(stats.deviation)}`
  ];
  return parts.join(' | ');
}

function runTrials(trialSizes) {
  const lines = [];
  for (const size of trialSizes) {
    const counts = simulateCoinTosses(size);
    lines.push(formatReport(counts));
  }
  return lines;
}

function main() {
  const trialSizes = [10, 5, 100, 1000];
  const report = runTrials(trialSizes);
  for (const line of report) {
    console.log(line);
  }
}

main();

module.exports = { simulateCoinTosses, summarize, formatReport, runTrials };

