function getInitials(fullName) {
  if (typeof fullName !== 'string') {
    throw new TypeError('getInitials expects a string');
  }
  const parts = fullName.trim().split(' ');
  const initials = [];
  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }
    const firstLetter = part.charAt(0);
    initials.push(firstLetter.toUpperCase());
  }
  return initials.join('');
}

function getMonogram(fullName, separator = '.') {
  const letters = getInitials(fullName).split('');
  if (letters.length === 0) {
    return '';
  }
  return letters.join(separator) + separator;
}

function abbreviateName(fullName) {
  const words = fullName.trim().split(' ').filter((word) => word.length > 0);
  if (words.length < 2) {
    return words.join('');
  }
  const surname = words[words.length - 1];
  const leading = words.slice(0, -1);
  const abbreviated = leading.map((word) => `${word.charAt(0).toUpperCase()}.`);
  abbreviated.push(surname);
  return abbreviated.join(' ');
}

function buildReport(names) {
  const rows = names.map((name) => {
    const initials = getInitials(name);
    return {
      name: name.trim(),
      initials,
      monogram: getMonogram(name),
      short: abbreviateName(name)
    };
  });
  const widest = rows.reduce((max, row) => Math.max(max, row.name.length), 0);
  const lines = rows.map((row) => {
    const padded = row.name.padEnd(widest, ' ');
    return `${padded} | ${row.initials} | ${row.monogram} | ${row.short}`;
  });
  return lines.join('\n');
}

function main() {
  const samples = [
    'John Doe',
    'Alice B. Wonderland',
    '  grace   hopper ',
    'Prince'
  ];
  console.log(getInitials('John Doe'));
  console.log(getInitials('Alice B. Wonderland'));
  console.log(buildReport(samples));

  let failures = 0;
  const expectations = [['John Doe', 'JD'], ['Alice B. Wonderland', 'ABW']];
  for (const [input, expected] of expectations) {
    const actual = getInitials(input);
    if (actual !== expected) {
      failures += 1;
      console.error(`Mismatch for "${input}": got ${actual}, want ${expected}`);
    }
  }
  return failures === 0 ? 0 : 1;
}

main();

