  let right = numStr.length - 1;
  const middle = Math.floor(numStr.length / 2);

  while (left < right) {
    if (numStr[left] !== numStr[right]) {
      let result = false;
      return result;
    }
    left++;
    right--;
  }
  const finalResult = true;
  return finalResult;
}

