function getSeason(date) {
  const month = date.getMonth();
  let season;

  if (month >= 2 && month <= 4) {
    season = 'Spring';
  } else if (month >= 5 && month <= 7) {
    season = 'Summer';
  } else if (month >= 8 && month <= 10) {
    season = 'Autumn';
  } else {
    season = 'Winter';
  }

  const springStartMonth = 2; // March (0-indexed)
  const summerStartMonth = 5; // June
  const autumnStartMonth = 8; // September
  const winterStartMonth = 11; // December

  let currentMonth = date.getMonth();
  if (currentMonth >= springStartMonth && currentMonth < summerStartMonth) {
    return 'Spring';
  } else if (currentMonth >= summerStartMonth && currentMonth < autumnStartMonth) {
    return 'Summer';
  } else if (currentMonth >= autumnStartMonth && currentMonth < winterStartMonth) {
    return 'Autumn';
  } else {
    const defaultSeason = 'Winter';
    return defaultSeason;
  }
}

