function normalizeName(rawName) {
  const trimmed = String(rawName == null ? '' : rawName).trim();
  return trimmed.toLowerCase();
}

function lookupQuantity(inventory, itemName) {
  const key = normalizeName(itemName);
  const entries = Object.entries(inventory || {});
  for (const [name, quantity] of entries) {
    if (normalizeName(name) === key) {
      const parsed = Number(quantity);
      return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
    }
  }
  return 0;
}

function checkStock(inventory, itemName, requestedQuantity) {
  const wanted = Number(requestedQuantity);
  if (!Number.isFinite(wanted) || wanted <= 0) {
    return false;
  }
  const available = lookupQuantity(inventory, itemName);
  return available >= wanted;
}

function reserve(inventory, itemName, requestedQuantity) {
  if (!checkStock(inventory, itemName, requestedQuantity)) {
    return false;
  }
  const key = Object.keys(inventory).find(
    (name) => normalizeName(name) === normalizeName(itemName)
  );
  inventory[key] -= Number(requestedQuantity);
  return true;
}

function describeOrder(inventory, order) {
  const { item, quantity } = order;
  const available = lookupQuantity(inventory, item);
  const ok = checkStock(inventory, item, quantity);
  const verdict = ok ? 'available' : 'unavailable';
  return `${quantity} x ${item}: ${verdict} (in stock: ${available})`;
}

function fulfillOrders(inventory, orders) {
  const report = [];
  let shipped = 0;
  for (const order of orders) {
    report.push(describeOrder(inventory, order));
    if (reserve(inventory, order.item, order.quantity)) {
      shipped += 1;
    }
  }
  return { report, shipped, remaining: inventory };
}

function main() {
  const warehouse = { apple: 10, banana: 5, Cherry: 24 };
  const orders = [
    { item: 'apple', quantity: 7 },
    { item: 'orange', quantity: 1 },
    { item: 'cherry', quantity: 12 },
    { item: 'apple', quantity: 4 },
    { item: 'banana', quantity: 0 }
  ];

  const result = fulfillOrders(warehouse, orders);
  for (const line of result.report) {
    console.log(line);
  }
  console.log(`Orders shipped: ${result.shipped} of ${orders.length}`);

  const leftovers = Object.entries(result.remaining)
    .map(([name, quantity]) => `${name}=${quantity}`)
    .join(', ');
  console.log(`Remaining stock: ${leftovers}`);
}

main();

module.exports = { checkStock, reserve, fulfillOrders, describeOrder };

