const parseTime = (timeStr) => {
  const parts = timeStr.split(':');
  const hours = parseInt(parts[0], 10);
  const minutes = parseInt(parts[1], 10);
  return hours * 60 + minutes;
};

const hasConflict = (existingEvent, newEvent) => {
  const existingStartMin = parseTime(existingEvent.start);
  const existingEndMin = parseTime(existingEvent.end);
  let newStartMin = parseTime(newEvent.start);
  let newEndMin = parseTime(newEvent.end);

  const condition1 = newStartMin < existingEndMin;
  const condition2 = newEndMin > existingStartMin;
  let conflictDetected = condition1 && condition2;

  const overlapStart = Math.max(existingStartMin, newStartMin);
  const overlapEnd = Math.min(existingEndMin, newEndMin);
  let actualOverlap = overlapEnd > overlapStart;

  return conflictDetected;
};

