const TOO_HIGH = 'Too High';
const TOO_LOW = 'Too Low';
const CORRECT = 'Correct!';

function checkGuess(secretNumber, guess) {
  const secret = Number(secretNumber);
  const attempt = Number(guess);

  if (!Number.isFinite(secret) || !Number.isFinite(attempt)) {
    throw new TypeError('checkGuess requires two numeric arguments');
  }

  if (attempt > secret) {
    return TOO_HIGH;
  }
  if (attempt < secret) {
    return TOO_LOW;
  }
  return CORRECT;
}

function parseGuess(raw) {
  const trimmed = String(raw).trim();
  if (trimmed === '') {
    throw new Error('Empty guess');
  }
  const value = Number(trimmed);
  if (!Number.isInteger(value)) {
    throw new Error(`"${trimmed}" is not a whole number`);
  }
  return value;
}

function playRounds(secretNumber, rawGuesses) {
  const rounds = [];
  let solved = false;

  for (const raw of rawGuesses) {
    if (solved) {
      break;
    }
    const guess = parseGuess(raw);
    const result = checkGuess(secretNumber, guess);
    rounds.push({ guess, result });
    solved = result === CORRECT;
  }

  return { rounds, solved };
}

function formatReport(secretNumber, rawGuesses) {
  const { rounds, solved } = playRounds(secretNumber, rawGuesses);
  const lines = rounds.map((round, index) => {
    const label = `Round ${index + 1}`;
    return `${label}: guessed ${round.guess} -> ${round.result}`;
  });

  const summary = solved
    ? `Found ${secretNumber} in ${rounds.length} guess(es).`
    : `Secret ${secretNumber} was never guessed.`;

  lines.push(summary);
  return lines.join('\n');
}

function main() {
  const secret = 5;
  const guesses = ['7', '2', ' 5 ', '9'];
  console.log(formatReport(secret, guesses));

  const single = checkGuess(secret, 7);
  console.log(`Direct call: ${single}`);
}

main();

module.exports = { checkGuess, parseGuess, playRounds, formatReport };

