const parseQueryString = (queryString) => {
  let result = {};
  let cleanString = queryString;

  if (queryString.startsWith('?')) {
    cleanString = queryString.substring(1);
  }

  let pairs = cleanString.split('&');
  const numPairs = pairs.length;

  for (let i = 0; i < numPairs; i++) {
    const pair = pairs[i];
    let parts = pair.split('=');
    const key = parts[0];
    let value = parts[1];
    if (value === undefined) {
        value = '';
    }
    result[key] = value;
  }

  return result;
};

