const areAnagrams = (str1, str2) => {
  let cleanedStr1 = str1.toLowerCase().replace(/[^a-z]/g, '');
  let cleanedStr2 = str2.toLowerCase().replace(/[^a-z]/g, '');

  if (cleanedStr1.length !== cleanedStr2.length) {
    return false;
  }

  const charCount1 = {};
  const charCount2 = {};
  let i = 0;

  while (i < cleanedStr1.length) {
    let char = cleanedStr1[i];
    charCount1[char] = (charCount1[char] || 0) + 1;
    i++;
  }

  let j = 0;
  while (j < cleanedStr2.length) {
    let char = cleanedStr2[j];
    charCount2[char] = (charCount2[char] || 0) + 1;
    j++;
  }

  for (const char in charCount1) {
    if (charCount1[char] !== charCount2[char]) {
      return false;
    }
  }

  return true;
};

