function filterStringsByLength(strings, minLength) {
  if (!Array.isArray(strings)) {
    throw new TypeError('filterStringsByLength expects an array of strings');
  }
  const limit = Number(minLength);
  if (!Number.isFinite(limit)) {
    throw new TypeError('minLength must be a finite number');
  }
  const result = [];
  for (const value of strings) {
    if (typeof value !== 'string') {
      throw new TypeError(`expected a string, received ${typeof value}`);
    }
    if (value.length >= limit) {
      result.push(value);
    }
  }
  return result;
}

function longestString(strings) {
  let longest = '';
  for (const value of strings) {
    if (value.length > longest.length) {
      longest = value;
    }
  }
  return longest;
}

function summarize(strings, minLength) {
  const kept = filterStringsByLength(strings, minLength);
  const dropped = strings.length - kept.length;
  let averageLength = 0;
  if (kept.length > 0) {
    const total = kept.reduce((sum, value) => sum + value.length, 0);
    averageLength = total / kept.length;
  }
  return {
    kept,
    dropped,
    longest: longestString(kept),
    averageLength: Number(averageLength.toFixed(2)),
  };
}

function formatSummary(report, minLength) {
  const lines = [`strings of length ${minLength} or more: ${report.kept.length}`];
  lines.push(`  kept: ${report.kept.length ? report.kept.join(', ') : '(none)'}`);
  lines.push(`  dropped: ${report.dropped}`);
  if (report.kept.length > 0) {
    lines.push(`  longest: ${report.longest} (${report.longest.length} chars)`);
    lines.push(`  average length: ${report.averageLength}`);
  }
  return lines.join('\n');
}

function main() {
  const cases = [
    { strings: ['apple', 'cat', 'banana'], minLength: 4 },
    { strings: ['a', 'bb', 'ccc'], minLength: 2 },
    { strings: ['tiny', 'x'], minLength: 10 },
  ];
  for (const { strings, minLength } of cases) {
    const report = summarize(strings, minLength);
    console.log(formatSummary(report, minLength));
    console.log('');
  }
}

main();

module.exports = { filterStringsByLength, longestString, summarize, formatSummary };

