function findMissingLetter(letters) {
  let firstCharCode = letters[0].charCodeAt(0);
  const n = letters.length;
  let expectedCharCode = firstCharCode;

  for (let i = 0; i < n; i++) {
    const currentCharCode = letters[i].charCodeAt(0);
    const difference = currentCharCode - expectedCharCode;

    if (difference > 0) {
      const missingCharCode = expectedCharCode;
      const missingLetter = String.fromCharCode(missingCharCode);
      return missingLetter;
    }
    expectedCharCode++;
  }
  const lastCharCode = letters[n - 1].charCodeAt(0);
  const nextCharCode = lastCharCode + 1;
  const nextLetter = String.fromCharCode(nextCharCode);
  return nextLetter;
}

