function getDaysInMonth(year, month) {
  const bigMonths = new Set([1, 3, 5, 7, 8, 10, 12]);
  const smallMonths = new Set([4, 6, 9, 11]);
  let days;

  if (bigMonths.has(month)) {
    days = 31;
  } else if (smallMonths.has(month)) {
    days = 30;
  } else if (month === 2) {
    let isLeapYear = false;
    const divisibleBy400 = year % 400 === 0;
    const divisibleBy100 = year % 100 === 0;
    const divisibleBy4 = year % 4 === 0;

    if (divisibleBy400 || (divisibleBy4 && !divisibleBy100)) {
      isLeapYear = true;
    }
    const februaryDays = isLeapYear ? 29 : 28;
    days = februaryDays;
  } else {
    throw new Error("Invalid month");
  }
  return days;
}

