const decodeCaesarCipher = (encryptedText, shift) => {
  let decodedText = '';
  const alphabetLength = 26;
  let charCodeA = 'a'.charCodeAt(0);

  for (let i = 0; i < encryptedText.length; i++) {
    const char = encryptedText[i];
    let charCode = char.charCodeAt(0);

    if (char >= 'a' && char <= 'z') {
      let originalCharCode = charCode - charCodeA;
      let decodedCharCode = (originalCharCode - shift + alphabetLength) % alphabetLength;
      let newChar = String.fromCharCode(decodedCharCode + charCodeA);
      decodedText += newChar;
    } else {
      decodedText += char; // Append non-alphabetic characters as is
    }
  }
  return decodedText;
};

