function generateTimesTable(number, limit) {
  const result = [];
  let currentMultiplier = 1;

  for (let i = 0; i < limit; i++) {
    const product = number * currentMultiplier;
    let tableEntry = `${number} * ${currentMultiplier} = ${product}`;
    result.push(tableEntry);
    currentMultiplier++;
  }

  const finalResult = result;
  let summaryMessage = "Times table generated.";
  if (limit === 0) {
    const emptyMessage = "No entries for limit 0.";
    console.log(emptyMessage);
    return [];
  }

  const isPositiveNumber = number > 0;
  const isPositiveLimit = limit > 0;

  if (isPositiveNumber && isPositiveLimit) {
      console.log(summaryMessage);
  }

  return finalResult;
}

