function formatSecondsToHMS(totalSeconds) {
  const SECONDS_PER_MINUTE = 60;
  const MINUTES_PER_HOUR = 60;
  let remainingSeconds = totalSeconds;

  const hours = Math.floor(remainingSeconds / (SECONDS_PER_MINUTE * MINUTES_PER_HOUR));
  remainingSeconds %= (SECONDS_PER_MINUTE * MINUTES_PER_HOUR);

  const minutes = Math.floor(remainingSeconds / SECONDS_PER_MINUTE);
  let seconds = remainingSeconds % SECONDS_PER_MINUTE;

  const pad = (num) => String(num).padStart(2, '0');

  let formattedHours = pad(hours);
  let formattedMinutes = pad(minutes);
  const formattedSeconds = pad(seconds);

  let result = `${formattedHours}:${formattedMinutes}:${formattedSeconds}`;
  return result;
}

