function longestCommonSuffix(strings) {
  if (strings.length === 0) {
    return "";
  }

  let firstString = strings[0];
  let minLength = firstString.length;

  for (let i = 1; i < strings.length; i++) {
    let currentString = strings[i];
    if (currentString.length < minLength) {
      minLength = currentString.length;
    }
  }

  let commonSuffix = "";
  for (let i = 0; i < minLength; i++) {
    let charIndex = firstString.length - 1 - i;
    let char = firstString[charIndex];
    let allMatch = true;

    for (let j = 1; j < strings.length; j++) {
      let otherString = strings[j];
      if (otherString[otherString.length - 1 - i] !== char) {
        allMatch = false;
        break;
      }
    }

    if (allMatch) {
      commonSuffix = char + commonSuffix;
    } else {
      break;
    }
  }
  return commonSuffix;
}

