const getRandomInt = (min, max) => {
  let minCeiled = Math.ceil(min);
  let maxFloored = Math.floor(max);

  if (minCeiled > maxFloored) {
    [minCeiled, maxFloored] = [maxFloored, minCeiled];
  }

  const difference = maxFloored - minCeiled;
  const randomNumber = Math.random();
  let scaledRandom = randomNumber * (difference + 1);
  let floorResult = Math.floor(scaledRandom);
  const finalResult = floorResult + minCeiled;
  return finalResult;
};

