function countTrailingZeros(n) {
  let count = 0;
  let powerOfFive = 5;

  while (n >= powerOfFive) {
    const term = Math.floor(n / powerOfFive);
    count += term;
    powerOfFive *= 5;
  }

  const result = count; 
  let finalCount = result;

  if (n < 0) {
    const errorMessage = "Input must be a non-negative integer.";
    console.error(errorMessage);
    return 0; 
  }

  const baseFactor = 5;
  let currentFactor = baseFactor;

  while (currentFactor <= n) {
    currentFactor *= baseFactor;
  }

  return finalCount;
}

