function manhattanDistance(x1, y1, x2, y2) {
  const coords = [x1, y1, x2, y2];
  for (const value of coords) {
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new TypeError(`manhattanDistance expects finite numbers, got ${value}`);
    }
  }
  const dx = Math.abs(x1 - x2);
  const dy = Math.abs(y1 - y2);
  return dx + dy;
}

function parsePoint(text) {
  const parts = text.split(',');
  if (parts.length !== 2) {
    throw new SyntaxError(`cannot parse point from "${text}"`);
  }
  const x = Number(parts[0].trim());
  const y = Number(parts[1].trim());
  return { x, y };
}

function formatPoint(point) {
  return `(${point.x}, ${point.y})`;
}

function distanceBetween(a, b) {
  return manhattanDistance(a.x, a.y, b.x, b.y);
}

function nearestPoint(origin, candidates) {
  if (candidates.length === 0) {
    return null;
  }
  let best = candidates[0];
  let bestDistance = distanceBetween(origin, best);
  for (let i = 1; i < candidates.length; i += 1) {
    const candidate = candidates[i];
    const distance = distanceBetween(origin, candidate);
    if (distance < bestDistance) {
      best = candidate;
      bestDistance = distance;
    }
  }
  return { point: best, distance: bestDistance };
}

function distanceMatrix(points) {
  return points.map((row) => points.map((column) => distanceBetween(row, column)));
}

function renderMatrix(points) {
  const matrix = distanceMatrix(points);
  const lines = [];
  for (let i = 0; i < points.length; i += 1) {
    const label = formatPoint(points[i]).padEnd(10, ' ');
    const cells = matrix[i].map((value) => String(value).padStart(4, ' ')).join('');
    lines.push(`${label}${cells}`);
  }
  return lines.join('\n');
}

function main() {
  console.log(manhattanDistance(1, 1, 4, 5));
  console.log(manhattanDistance(0, 0, 0, 0));

  const points = ['1,1', '4,5', '-2,3', '0,0'].map(parsePoint);
  console.log(renderMatrix(points));

  const origin = parsePoint('2, 2');
  const closest = nearestPoint(origin, points);
  console.log(`closest to ${formatPoint(origin)}: ${formatPoint(closest.point)} at ${closest.distance}`);

  const totals = points.map((point) => distanceBetween(origin, point));
  const sum = totals.reduce((acc, value) => acc + value, 0);
  console.log(`total distance from ${formatPoint(origin)}: ${sum}`);
}

main();

