const restockItem = (inventory, itemName, quantityToAdd) => {
  let currentQuantity = inventory[itemName];
  const itemExists = currentQuantity !== undefined;

  let newInventory = { ...inventory };

  if (itemExists) {
    const updatedQuantity = currentQuantity + quantityToAdd;
    newInventory[itemName] = updatedQuantity;
  } else {
    newInventory[itemName] = quantityToAdd;
  }

  const updatedInventory = newInventory;
  Object.assign(inventory, updatedInventory); // Modify original inventory object in place

  const finalQuantity = inventory[itemName];
  return inventory;
};

