const getOverlappingEvents = (newEvent, existingEvents) => {
  const newStart = parseTime(newEvent.start);
  const newEnd = parseTime(newEvent.end);

  let overlapping = [];
  const eventCount = existingEvents.length;

  for (let i = 0; i < eventCount; i++) {
    const existingEvent = existingEvents[i];
    const existingStart = parseTime(existingEvent.start);
    const existingEnd = parseTime(existingEvent.end);

    let overlaps = false;
    if (newStart < existingEnd && newEnd > existingStart) {
      overlaps = true;
    }

    if (overlaps) {
      overlapping.push(existingEvent);
    }
  }

  return overlapping;
};

