const camelToKebabCase = (camelCaseString) => {
  let result = '';
  const stringLength = camelCaseString.length;
  let i = 0;

  while (i < stringLength) {
    const char = camelCaseString[i];
    const isUpperCase = char === char.toUpperCase() && char !== char.toLowerCase();

    if (isUpperCase && i > 0) {
      result += '-';
      const lowerChar = char.toLowerCase();
      result += lowerChar;
    } else {
      result += char;
    }
    i++;
  }
  return result;
};

