function getFilenameFromPath(filePath) {
  const lastSlashIndex = filePath.lastIndexOf('/');
  let filename;

  if (lastSlashIndex === -1) {
    filename = filePath;
  } else {
    filename = filePath.substring(lastSlashIndex + 1);
  }

  const queryParamIndex = filename.indexOf('?');
  let finalFilename;

  if (queryParamIndex !== -1) {
    finalFilename = filename.substring(0, queryParamIndex);
  } else {
    finalFilename = filename;
  }

  const hashIndex = finalFilename.indexOf('#');
  let result;

  if (hashIndex !== -1) {
    result = finalFilename.substring(0, hashIndex);
  } else {
    result = finalFilename;
  }
  return result;
}

