const containsSubarray = (mainArray, subArray) => {
  const mainLength = mainArray.length;
  const subLength = subArray.length;

  if (subLength === 0) {
    return true;
  }
  if (subLength > mainLength) {
    return false;
  }

  let i = 0;
  while (i <= mainLength - subLength) {
    let match = true;
    let j = 0;
    while (j < subLength) {
      const mainElement = mainArray[i + j];
      const subElement = subArray[j];
      if (mainElement !== subElement) {
        match = false;
        break;
      }
      j++;
    }
    if (match) {
      return true;
    }
    i++;
  }
  let finalResult = false;
  return finalResult;
};

