const DIMENSION_NAMES = ['b1', 'b2', 'h'];

function validateDimensions(values) {
  const problems = [];
  for (let index = 0; index < values.length; index += 1) {
    const name = DIMENSION_NAMES[index];
    const value = values[index];
    if (typeof value !== 'number' || Number.isNaN(value)) {
      problems.push(name + ' must be a number');
    } else if (!Number.isFinite(value)) {
      problems.push(name + ' must be finite');
    } else if (value <= 0) {
      problems.push(name + ' must be positive, got ' + value);
    }
  }
  return problems;
}

function calculateTrapezoidArea(b1, b2, h) {
  const problems = validateDimensions([b1, b2, h]);
  if (problems.length > 0) {
    throw new RangeError('Invalid trapezoid: ' + problems.join('; '));
  }
  return 0.5 * (b1 + b2) * h;
}

function describeTrapezoid(b1, b2, h) {
  const area = calculateTrapezoidArea(b1, b2, h);
  const midline = (b1 + b2) / 2;
  const kind = b1 === b2 ? 'parallelogram-like' : 'true trapezoid';
  return { bases: b1 + ' x ' + b2, height: h, midline: midline, area: area, kind: kind };
}

function formatRow(description) {
  const dims = (description.bases + ' x ' + description.height).padEnd(18);
  const midline = 'midline=' + description.midline.toFixed(2);
  const area = 'area=' + description.area.toFixed(2);
  return dims + (midline + ' ' + area).padEnd(30) + description.kind;
}

function buildReport(shapes) {
  const rows = [];
  let total = 0;
  for (let i = 0; i < shapes.length; i += 1) {
    const shape = shapes[i];
    const description = describeTrapezoid(shape[0], shape[1], shape[2]);
    total += description.area;
    rows.push(formatRow(description));
  }
  rows.push('total area of ' + shapes.length + ' shapes: ' + total.toFixed(2));
  return rows.join('\n');
}

function main() {
  const shapes = [
    [2, 4, 3],
    [5, 5, 2],
    [1.5, 6.5, 4]
  ];
  console.log(buildReport(shapes));
}

main();

