const DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const WEEKEND_DAYS = new Set([0, 6]);

function isWeekend(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new TypeError('isWeekend expects a valid Date object');
  }
  const day = date.getUTCDay();
  return WEEKEND_DAYS.has(day);
}

function dayName(date) {
  const index = date.getUTCDay();
  return DAY_NAMES[index];
}

function parseIsoDate(text) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text.trim());
  if (!match) {
    throw new RangeError(`not an ISO date: ${text}`);
  }
  const [, year, month, day] = match;
  const date = new Date(`${year}-${month}-${day}T00:00:00Z`);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`impossible calendar date: ${text}`);
  }
  return date;
}

function formatIsoDate(date) {
  return date.toISOString().slice(0, 10);
}

function weekendsInRange(start, end) {
  const cursor = new Date(start.getTime());
  const found = [];
  while (cursor.getTime() <= end.getTime()) {
    if (isWeekend(cursor)) {
      found.push(new Date(cursor.getTime()));
    }
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
  return found;
}

function describe(date) {
  const label = isWeekend(date) ? 'weekend' : 'weekday';
  return `${formatIsoDate(date)} is a ${dayName(date)} (${label})`;
}

function main() {
  const samples = ['2023-10-28', '2023-10-27', '2023-10-29', '2024-02-29'];
  for (const sample of samples) {
    const date = parseIsoDate(sample);
    console.log(describe(date));
  }

  const start = parseIsoDate('2023-10-23');
  const end = parseIsoDate('2023-11-05');
  const weekendDates = weekendsInRange(start, end);
  const listed = weekendDates.map(formatIsoDate).join(', ');
  console.log(`Weekend days between ${formatIsoDate(start)} and ${formatIsoDate(end)}: ${listed}`);

  const totalDays = Math.round((end.getTime() - start.getTime()) / 86400000) + 1;
  const share = (weekendDates.length / totalDays) * 100;
  console.log(`${weekendDates.length} of ${totalDays} days (${share.toFixed(0)}%) fall on a weekend`);
}

main();

module.exports = { isWeekend, dayName, parseIsoDate, formatIsoDate, weekendsInRange, describe };

