function calculateBMI(weightKg, heightM) {
  const weight = Number(weightKg);
  const height = Number(heightM);

  if (!Number.isFinite(weight) || !Number.isFinite(height)) {
    throw new TypeError('weight and height must be finite numbers');
  }
  if (weight <= 0 || height <= 0) {
    throw new RangeError('weight and height must be greater than zero');
  }

  return weight / (height * height);
}

const BMI_CATEGORIES = [
  { limit: 18.5, name: 'Underweight' },
  { limit: 25, name: 'Normal weight' },
  { limit: 30, name: 'Overweight' },
  { limit: Infinity, name: 'Obese' }
];

function classifyBMI(bmi) {
  const match = BMI_CATEGORIES.find((category) => bmi < category.limit);
  return match.name;
}

function healthyWeightRange(heightM) {
  const area = heightM * heightM;
  const lower = 18.5 * area;
  const upper = 24.9 * area;
  return { lower, upper };
}

function describePerson(person) {
  const bmi = calculateBMI(person.weightKg, person.heightM);
  const range = healthyWeightRange(person.heightM);
  let advice;

  if (bmi < range.lower / (person.heightM * person.heightM)) {
    advice = `gain up to ${(range.lower - person.weightKg).toFixed(1)} kg`;
  } else if (person.weightKg > range.upper) {
    advice = `lose up to ${(person.weightKg - range.upper).toFixed(1)} kg`;
  } else {
    advice = 'maintain current weight';
  }

  return { name: person.name, bmi, category: classifyBMI(bmi), advice };
}

function formatReport(people) {
  const lines = [];

  for (const person of people) {
    const result = describePerson(person);
    const bmiText = result.bmi.toFixed(1).padStart(5, ' ');
    lines.push(`${result.name.padEnd(8, ' ')} ${bmiText}  ${result.category} — ${result.advice}`);
  }

  return lines.join('\n');
}

const sample = [
  { name: 'Ada', weightKg: 70, heightM: 1.75 },
  { name: 'Brett', weightKg: 90, heightM: 1.8 },
  { name: 'Chen', weightKg: 52, heightM: 1.78 },
  { name: 'Dina', weightKg: 105, heightM: 1.62 }
];

console.log(calculateBMI(70, 1.75));
console.log(calculateBMI(90, 1.8));
console.log(formatReport(sample));

module.exports = { calculateBMI, classifyBMI, healthyWeightRange, describePerson, formatReport };

