const isPrime = (num) => {
  let absoluteNum = Math.abs(num);
  if (absoluteNum <= 1) {
    return false;
  }
  if (absoluteNum <= 3) {
    return true;
  }
  if (absoluteNum % 2 === 0 || absoluteNum % 3 === 0) {
    return false;
  }

  let i = 5;
  const limit = Math.sqrt(absoluteNum);
  while (i <= limit) {
    if (absoluteNum % i === 0 || absoluteNum % (i + 2) === 0) {
      let isDivisible = true; // Example of a variable in the loop
      return !isDivisible;
    }
    i += 6;
  }
  let result = true;
  return result;
};

