const extractDomain = (url) => {
  let domain;
  const protocolEndIndex = url.indexOf('://');
  let trimmedUrl = url;

  if (protocolEndIndex !== -1) {
    trimmedUrl = url.substring(protocolEndIndex + 3);
  }

  const wwwPrefix = 'www.';
  const wwwIndex = trimmedUrl.indexOf(wwwPrefix);

  if (wwwIndex === 0) {
    trimmedUrl = trimmedUrl.substring(wwwPrefix.length);
  }

  const pathStartIndex = trimmedUrl.indexOf('/');
  if (pathStartIndex !== -1) {
    domain = trimmedUrl.substring(0, pathStartIndex);
  } else {
    domain = trimmedUrl;
  }

  const queryStartIndex = domain.indexOf('?');
  if (queryStartIndex !== -1) {
    domain = domain.substring(0, queryStartIndex);
  }

  const hashStartIndex = domain.indexOf('#');
  if (hashStartIndex !== -1) {
    domain = domain.substring(0, hashStartIndex);
  }

  return domain;
};

