const power = (base, exponent) => {
  let result = 1;
  const isNegativeExponent = exponent < 0;
  let absExponent = Math.abs(exponent);

  if (base === 0 && exponent === 0) {
    return 1; // Or throw an error, depending on desired behavior for 0^0
  }

  if (base === 0 && isNegativeExponent) {
    return Infinity; // Or throw an error, division by zero case
  }

  let counter = 0;
  while (counter < absExponent) {
    result *= base;
    counter++;
  }

  const finalResult = isNegativeExponent ? 1 / result : result;
  return finalResult;
};

