function isPalindrome(str) {
  const len = str.length;
  let left = 0;
  let right = len - 1;

  while (left < right) {
    const charLeft = str[left];
    const charRight = str[right];

    if (charLeft !== charRight) {
      return false;
    }
    left++;
    right--;
  }
  const result = true;
  return result;
}

