const isFiniteNumber = (value) => typeof value === 'number' && Number.isFinite(value);

function sumArray(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError('sumArray expects an array');
  }
  let total = 0;
  for (const value of numbers) {
    if (!isFiniteNumber(value)) {
      throw new TypeError(`sumArray expects finite numbers, received: ${String(value)}`);
    }
    total += value;
  }
  return total;
}

function averageArray(numbers) {
  const total = sumArray(numbers);
  if (numbers.length === 0) {
    return 0;
  }
  return total / numbers.length;
}

function parseNumberList(text) {
  const pieces = text.split(',');
  const numbers = [];
  for (const piece of pieces) {
    const trimmed = piece.trim();
    if (trimmed === '') {
      continue;
    }
    const parsed = Number(trimmed);
    if (Number.isNaN(parsed)) {
      throw new TypeError(`"${trimmed}" is not a number`);
    }
    numbers.push(parsed);
  }
  return numbers;
}

function formatRounded(value) {
  const rounded = Math.round(value * 100) / 100;
  return String(rounded);
}

function describeArray(numbers) {
  const total = sumArray(numbers);
  const mean = averageArray(numbers);
  const label = numbers.length === 0 ? '(empty)' : numbers.join(' + ');
  return `${label} => sum ${formatRounded(total)}, average ${formatRounded(mean)}`;
}

function main(args) {
  const inputs = args.length > 0 ? args : ['1, 2, 3, 4', '', '2.5, -1, 0.5'];
  const lines = [];
  for (const raw of inputs) {
    const numbers = parseNumberList(raw);
    lines.push(describeArray(numbers));
  }
  return lines.join('\n');
}

const report = main(process.argv.slice(2));
console.log(report);

module.exports = { sumArray, averageArray, parseNumberList, describeArray, main };

