function truncateString(str, maxLength) {
  const ellipsis = '...';
  let result = str;

  if (str.length > maxLength) {
    const availableLength = maxLength - ellipsis.length;
    let truncatedPart;

    if (availableLength > 0) {
      truncatedPart = str.substring(0, availableLength);
      result = truncatedPart + ellipsis;
    } else {
      // If maxLength is too small to even fit ellipsis, just return ellipsis
      result = ellipsis;
    }
  }
  return result;
}

