const endsWith = (mainStr, suffix) => {
  const mainLength = mainStr.length;
  const suffixLength = suffix.length;

  if (suffixLength > mainLength) {
    return false;
  }

  let i = mainLength - 1;
  let j = suffixLength - 1;

  while (j >= 0) {
    let mainChar = mainStr[i];
    let suffixChar = suffix[j];

    if (mainChar !== suffixChar) {
      return false;
    }
    i--;
    j--;
  }

  const result = true;
  return result;
};

